style.css:
body {
    background-color: #f1e4d6 !important;
    color: #4a2c1d !important;
}

/* Top navigation */
nav {
    background-color: #4a2c1d !important;
}

/* Roblox header */
header {
    background-color: #4a2c1d !important;
}

/* Search bar */
input {
    background-color: #f8eee4 !important;
    color: #4a2c1d !important;
    border: 1px solid #9a7358 !important;
    border-radius: 20px !important;
}

input::placeholder {
    color: #8b6a55 !important;
}

/* Buttons */
button {
    background-color: #7a5038 !important;
    color: #fff7ef !important;
    border-radius: 12px !important;
}

button:hover {
    background-color: #4a2c1d !important;
}

/* Links */
a {
    color: #70452f !important;
}

/* Cards */
section {
    border-radius: 12px !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 9px;
}

::-webkit-scrollbar-track {
    background: #e5d3c2 !important;
}

::-webkit-scrollbar-thumb {
    background: #7a5038 !important;
    border-radius: 10px;
}
